-- DROP PROCEDURE "HadoopMigration".updatecontroltable();

CREATE OR REPLACE PROCEDURE "HadoopMigration".updatecontroltable()
 LANGUAGE plpgsql
AS $procedure$
	DECLARE
	
	--Digital Wallet KE BNPL Prod
	totalcount  INTEGER := 0;
	mincounter INTEGER := 0;
	maxcounter INTEGER := 0;
	BEGIN
	 
	---account
	select count(*) INTO totalcount from "HadoopMigration".account_hadoop  ; -- WHERE (account_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.createdon < CURRENT_DATE) ; -- OR (account_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.modifiedon < CURRENT_DATE);																									
	select min(sequenceid) INTO mincounter from "HadoopMigration".account_hadoop ; -- WHERE (account_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.createdon < CURRENT_DATE) ; -- OR (account_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.modifiedon < CURRENT_DATE);																									
	select max(sequenceid) INTO maxcounter from "HadoopMigration".account_hadoop ; -- WHERE (account_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.createdon < CURRENT_DATE) ; -- OR (account_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND account_hadoop.modifiedon < CURRENT_DATE);																									
	INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('account',totalcount,mincounter,maxcounter,current_date, current_date - 1 );
	
	
	--accountbalance
	
	select count(*) INTO totalcount from "HadoopMigration".accountbalance_hadoop  ; -- WHERE (accountbalance_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.createdon < CURRENT_DATE) ; -- OR (accountbalance_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.modifiedon < CURRENT_DATE);																									
	select min(sequenceid) INTO mincounter from "HadoopMigration".accountbalance_hadoop ; -- WHERE (accountbalance_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.createdon < CURRENT_DATE) ; -- OR (accountbalance_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.modifiedon < CURRENT_DATE);																									
	select max(sequenceid) INTO maxcounter from "HadoopMigration".accountbalance_hadoop ; -- WHERE (accountbalance_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.createdon < CURRENT_DATE) ; -- OR (accountbalance_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND accountbalance_hadoop.modifiedon < CURRENT_DATE);																									
	INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('accountbalance',totalcount,mincounter,maxcounter,current_date, current_date - 1 );
	
		
	--artthamasterdata
	select count(*) INTO totalcount from "HadoopMigration".artthamasterdata_hadoop  ; -- WHERE (artthamasterdata_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.createdon < CURRENT_DATE) ; -- OR (artthamasterdata_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.modifiedon < CURRENT_DATE);																									
	select min(sequenceid) INTO mincounter from "HadoopMigration".artthamasterdata_hadoop ; -- WHERE (artthamasterdata_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.createdon < CURRENT_DATE) ; -- OR (artthamasterdata_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.modifiedon < CURRENT_DATE);																									
	select max(sequenceid) INTO maxcounter from "HadoopMigration".artthamasterdata_hadoop ; -- WHERE (artthamasterdata_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.createdon < CURRENT_DATE) ; -- OR (artthamasterdata_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND artthamasterdata_hadoop.modifiedon < CURRENT_DATE);																									
	INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('artthamasterdata',totalcount,mincounter,maxcounter,current_date, current_date - 1 );	
	
	--authenticationpolicyconfig
	select count(*) INTO totalcount from "HadoopMigration".authenticationpolicyconfig_hadoop  ; -- WHERE (authenticationpolicyconfig_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.createdon < CURRENT_DATE) ; -- OR (authenticationpolicyconfig_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.modifiedon < CURRENT_DATE);																									
	select min(sequenceid) INTO mincounter from "HadoopMigration".authenticationpolicyconfig_hadoop ; -- WHERE (authenticationpolicyconfig_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.createdon < CURRENT_DATE) ; -- OR (authenticationpolicyconfig_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.modifiedon < CURRENT_DATE);																									
	select max(sequenceid) INTO maxcounter from "HadoopMigration".authenticationpolicyconfig_hadoop ; -- WHERE (authenticationpolicyconfig_hadoop.createdon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.createdon < CURRENT_DATE) ; -- OR (authenticationpolicyconfig_hadoop.modifiedon >= (CURRENT_DATE - '1 day'::interval) AND authenticationpolicyconfig_hadoop.modifiedon < CURRENT_DATE);																									
	INSERT INTO "HadoopMigration".hadoop_migration_control_table VALUES ('authenticationpolicyconfig',totalcount,mincounter,maxcounter,current_date, current_date - 1 );	
	
	--basicuser
