---Functions---
-- DROP PROCEDURE "dataReports".proc_rpt_crbreport_bnpl(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_crbreport_bnpl(IN requestid character varying, IN run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
begin
	truncate "dataReports".rpt_crbreport_bnpl;
	insert into "dataReports".rpt_crbreport_bnpl
SELECT 
		requestid,
		to_char(run_date::date::timestamp with time zone, 'yyyymmdd'::text) as "Business date",
		usr.lastname AS surname,
    	usr.firstname AS forename1,
    	usr.middlename AS forename2,
    	''::text AS forename3,
    	''::text AS tradingas,
    	to_char(usrc.dob::date::timestamp with time zone, 'yyyymmdd'::text)
    	AS date_of_birth,
    	usr.username AS client_number,
    	l.loanapplicationnumber as accountnumber,
        CASE
            WHEN usrc.gender::text = 'MALE'::text THEN 'M'::character varying
            WHEN usrc.gender::text = 'FEMALE'::text THEN 'F'::character varying
            ELSE usrc.gender
        END AS gender,
    	'KE'::text AS nationality,
        CASE
            WHEN usrc.identitytype::text = 'NATIONAL_ID'::text THEN '001'::character varying
            WHEN usrc.identitytype::text = 'PASSPORT'::text THEN '002'::character varying
            WHEN usrc.identitytype::text = 'ALIEN_REGISTRATION'::text THEN '003'::character varying
            WHEN usrc.identitytype::text = 'SERVICE_ID'::text THEN '004'::character varying
            ELSE usrc.identitytype
        END AS primaryid_type,
		usrc.identitynumber AS primaryid_num,
		concat('254', usr.username) AS mobilenumber,
		'I'::text AS accountproducttype,
		CASE
			--WHEN l.loanstatus::text = 'CLOSED'::text THEN to_char((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.repaymentduestatus not in ('EARLY_PAID') 
			WHEN l.loanstatus::text = 'CLOSED'::text THEN to_char((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID')
					order by paidon desc limit 1)::timestamp with time zone, 'yyyymmdd'::text)
			ELSE to_char((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
					order by installmentno limit 1)::timestamp with time zone, 'yyyymmdd'::text)
			END	AS installment_due_date,--CHANGE THIS BASED ON OLDEST DUE DATE
		round(l.principaldisbursed, 2) * 100::numeric AS originalamount,
		'KES'::text AS currencyoffacility,
    	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100 
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM platform_imp.loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID'))*100
        end as current_balance_inkes,
     	CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
            ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM platform_imp.loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID'))*100
        END AS current_balance,
    	CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)*100
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)*100
			WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2) * 100
			WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
			ELSE  COALESCE((select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM platform_imp.loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') and l2.duedate < run_date)*100,0)
		END AS overdue_balance, -- Should be ZERO not blank
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date - '1 day'::interval THEN to_char(((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'yyyymmdd')
			WHEN l.calucatedclosedate > run_date - '1 day'::interval and ((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ) < run_date -  '1 day'::interval then to_char(((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'yyyymmdd')       
            ELSE ' '::text
        END AS overdue_date, -- CHANGE BASED ON DUE,DATE, If Overdue, Oldest Due Date, If updcoming due: should be empty
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
            WHEN date_part('days'::text, 
			(select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, 
            (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) * '-1'::integer::double precision
        END AS days_in_arrears,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN (select count(*) from platform_imp.loanschedule l2 where installmentstatus not in ('PAID') and l2.loanid=l.id)
			WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN (select count(*) from platform_imp.loanschedule l2 where installmentstatus not in ('PAID') and l2.loanid=l.id)
            ELSE (select count(*) from platform_imp.loanschedule l2 where installmentstatus not in ('PAID') and l2.loanid=l.id and duedate < run_date)
        END AS noofinstallmentinarrears,
		CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) < 31::double precision THEN 'A'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '31'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '90'::double precision THEN 'B'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '91'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '180'::double precision THEN 'C'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) >= '181'::double precision AND date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) <= '360'::double precision THEN 'D'::text
            WHEN date_part('days'::text, run_date - (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone) > 360::double precision THEN 'E'::text
            ELSE ''::text
        END AS "Prudential Risk Classification",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN 'F'::text
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'A'::text
            ELSE 'C'::text
        END AS accountstatus,
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::date::timestamp with time zone, 'yyyymmdd'::text)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN to_char(l.chargeoffdate::date::timestamp with time zone, 'yyyymmdd'::text)
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN to_char(l.writeoffdate::date::timestamp with time zone, 'yyyymmdd'::text)
            ELSE to_char(l.actualcloseddate::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS accountstatusdate,
    	l.loanperiod AS repaymentperiod,
    	to_char(l.actualdisbursementdate::date::timestamp with time zone, 'yyyymmdd'::text) AS disbursement_date,
    	(select round((l2.amountdueoutstanding), 2)* 100::numeric FROM platform_imp.loanschedule l2 WHERE l2.loanid = l.id order by installmentno asc limit 1)
			AS installment_amount,
    	--round(l.installmentamount, 2) * 100::numeric AS installment_amount,
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::date::timestamp with time zone, 'yyyymmdd'::text)
        END AS latest_pymt_date,
        CASE
            --WHEN l.lastinstallmentamount IS NULL THEN 0::numeric
            WHEN l.lastpaidamount IS NULL THEN 0::numeric
            ELSE round(l.lastpaidamount, 2) * 100::numeric
        END AS latest_pymt_amt
	FROM platform_imp.basicuser usr
		JOIN platform_imp.loan l ON usr.id= l.userid	and 
		(l.loanstatus in ('ACTIVE','WRITE_OFF','CHARGE_OFF') 
				or (l.loanstatus='CLOSED' and Date(l.actualcloseddate)=date(run_date))) and l.loanproductid='011d3bc1-4b5e-49b7-a103-bf1cecfac5c9'
	--	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
		LEFT JOIN platform_imp.loanbucket lb ON l.id::text = lb.loanid::text
		LEFT JOIN platform_imp.loanproduct lp ON l.loanproductid::text = lp.id::text
		JOIN platform_imp.customer usrc on usr.id = usrc.id
		left join platform_imp.loanchargeoffdata lcd on lcd.loanid = l.id;
		--JOIN platform_imp.walletbalance wt ON usr.id::text = wt.ownerid::text
	--WHERE wt.producttype::text = 'WALLET'::text;
	end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_gldetailsreport_bnpl(varchar);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_gldetailsreport_bnpl(IN requestid character varying)
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_gldetailsreport_bnpl;
insert into "dataReports".rpt_gldetailsreport_bnpl
select requestid,w2.externalwalletcode AS accountid, --w2.glaccountnumber AS accountid,
    w2.name AS description,
               'Business'::character varying customerid,
    'Business'::character varying AS mobilenumber,
        CASE
            WHEN w.creditamount > 0::numeric THEN 'Credit'::text
            ELSE 'Debit'::text
        END AS trxtype,
        CASE
            WHEN w.description IS NULL OR w.description::text = ''::text THEN ( SELECT b.name
               FROM platform_imp.businessproduct b
              WHERE b.id::text = w.businessproductid::text)
            ELSE w.description
        END AS trxdescription,
    w.businesstrxid AS serialid,
    w.createdon::timestamp(0) without time zone AS trxdate,
        CASE
            WHEN w.creditamount > 0::numeric THEN round(w.totalbalance - w.creditamount, 2)
            ELSE round(w.totalbalance + w.debitamount, 2)
        END AS openingbalance,
    round(w.creditamount, 2) AS creditamount,
    round(w.debitamount, 2) AS debitamount,
    round(w.totalbalance, 2) AS closingbalance
     FROM platform_imp.transaction w
     JOIN platform_imp.wallettype w2 ON w.wallettypeid::text = w2.id::text and
     (w.transactionstatus::text = 'PROCESSED'::text OR w.transactionstatus::text = 'FAILED'::text)
              and w.createdon >= (concat(now()::date - 1,' ', '00:00:00')::timestamp without time zone)
              and  w.createdon <= (concat(now()::date - 1,' ', '23:59:59')::timestamp without time zone)
  ORDER BY w.createdon DESC;
  End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_income_accrual_report_bnpl(varchar, date, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_income_accrual_report_bnpl(IN requestid character varying, IN start_date date DEFAULT ((now())::date - (date_part('days'::text, (date_trunc('month'::text, (((now())::date - 28))::timestamp with time zone) + '1 mon -1 days'::interval)))::integer), IN end_date date DEFAULT ((now())::date - 1))
 LANGUAGE plpgsql
AS $procedure$
begin
truncate "dataReports".rpt_income_accrual_report_bnpl;
insert into "dataReports".rpt_income_accrual_report_bnpl
select requestid,interestacc.date,interestacc.amount, penalty.amount , facility.amount
from (select date(w.createdon),sum(creditamount) as amount
from platform_imp."transaction" w
where w.wallettypeid ='67ef539a-7fd7-4cbc-b73a-7df64fd737d2' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) interestacc
join (select date(w.createdon),sum(creditamount) as amount
from platform_imp."transaction" w
where w.wallettypeid ='1dbb3a71-525a-475a-bcca-d05b8967f7d5' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) penalty on penalty.date = interestacc.date
join (select date(w.createdon),sum(creditamount) as amount
from platform_imp."transaction" w
where w.wallettypeid ='d19a8eb2-d054-4629-a095-c9e72ee6c2e1' and w.creditamount > 0 and date(w.createdon) >= start_date and date(w.createdon) <= end_date
group by date(w.createdon)) facility on facility.date = penalty.date;
end;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_u756loanreportactive_bnpl(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_u756loanreportactive_bnpl(IN requestid character varying, IN run_date date DEFAULT (now() - '1 day'::interval))
 LANGUAGE plpgsql
AS $procedure$
Begin
truncate "dataReports".rpt_u756loanreportactive_bnpl;
insert into "dataReports".rpt_u756loanreportactive_bnpl
select 
		requestid,usr.lastname AS "Surname",
	    usr.firstname AS "Forename1",
	    usr.middlename AS "Forename2",
       /* CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title 
        END AS "Salutation", */
	    '' AS "Salutation",
    	to_char(run_date - '1 day'::interval,'dd/mm/yyyy') AS "BusinessDate", 
		to_char(dob::DATE,'dd/mm/yyyy') AS "Date_of_Birth",
	    usr.id AS "Client_Number",
	    l.loanapplicationnumber AS "Mobile_Loan_Account_Number",
	    usrc.gender,
    	'KE'::text AS "Nationality",
	    usrc.identitytype AS "PrimaryID_type",
	    usrc.identitynumber AS "PrimaryID_Num",
	    concat('254', usr.username) AS "Mobile_Number",
	    'KE'::text AS "Postal_Country",
	    0 AS salary_band,
	    'Virtual Banking'::text AS "Lender_Branch_Name",
	    160 AS "Lender_Branch_Code",
	    'IN001'::text AS "Account_prod_type",
	    to_char(l.expecteddisbursementdate::DATE,'dd/mm/yyyy') AS "Date_Acct_Opened",
	    CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN to_char((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
					order by installmentno desc limit 1)::timestamp with time zone, 'dd/mm/yyyy')
			ELSE to_char((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
					order by installmentno limit 1)::timestamp with time zone, 'dd/mm/yyyy') 
			END	AS "Instalment_due_date",
	    round(l.principaldisbursed, 2) AS "Original_Amount",
	    round(l.principaldisbursed, 2) AS local_orig_amount,
		CASE
			WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
            else (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM platform_imp.loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))
        END AS "Current_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN round(l.totalamountoutstanding, 2)
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2)
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
            WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
            ELSE COALESCE((select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2)  FROM platform_imp.loanschedule l2 
            WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') and l2.duedate < run_date),0)
            END AS "Overdue_balance",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN ' '::text
            WHEN l.calucatedclosedate < run_date - '1 day'::interval THEN to_char(((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'dd/mm/yyyy')
			WHEN l.calucatedclosedate > run_date - '1 day'::interval and ((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ) < run_date -  '1 day'::interval then to_char(((select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') order by installmentno limit 1 ) :: DATE + 1 ),'dd/mm/yyyy')       
            ELSE ' '::text
        END AS "Overdue_date",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::double precision
			WHEN date_part('days'::text, 
			(select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) >= 0::double precision THEN 0::double precision
            ELSE date_part('days'::text, 
            (select l2.duedate	FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') 
				order by installmentno limit 1)::timestamp with time zone - run_date - '1 day'::interval) * '-1'::integer::double precision
        END AS "Days_in_arrears",
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 'Bucket 0'::text
           	ELSE concat('Bucket ', round(lb.currentbucketnumber, 0))
        END AS "Bucket",
        CASE
				WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
				WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending+lcd.interestchargedoffpending+lcd.penaltychargedoffpending+lcd.chargeoffinterestpending, 2)
                WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN round(l.totalamountwrittenoff, 2)
			    WHEN l.totalamountoutstanding IS NULL THEN 0::numeric
				ELSE (select round(sum(l2.interestpending+l2.principalpending+l2.penaltypending), 2) FROM platform_imp.loanschedule l2 
				WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID') and l2.duedate < run_date)
			END as "Instalment_arrears",
    	l.loanstatus AS "Account_Status",
        CASE
            WHEN l.loanstatus::text = 'ACTIVE'::text THEN to_char(l.createdon::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN to_char(l.chargeoffdate::DATE,'dd/mm/yyyy')
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN to_char(l.writeoffdate::DATE,'dd/mm/yyyy')
            else to_char(l.actualcloseddate::DATE,'dd/mm/yyyy')
        END AS "Account_status_Date",
		' '::text AS "Reason_For_Closure",
		l.loanperiod AS "Repayment_period",
    	''::text AS "Deferred_pymt_Date",
    	''::text AS "Deferred_pymt_amt",
		l.replayfrequency AS "Payment_freq",
		to_char(l.actualdisbursementdate::DATE,'dd/mm/yyyy') AS "Disbursement_Date",
		(select round((l2.amountdueoutstanding), 2) FROM platform_imp.loanschedule l2 WHERE l2.loanid = l.id order by installmentno asc limit 1)
			AS "Instalment_amount",  -- add line
	   -- round(l.installmentamount, 2) AS "Instalment_amount",    --installmentamount
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::DATE,'dd/mm/yyyy')::text
        END AS "Latest_pymt_date",
    	COALESCE(round(l.lastpaidamount, 2), 0::numeric) AS "Latest_pymt_Amt",
    	--    	COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        CASE
            WHEN l.loanstatus::text = ANY (ARRAY['ACTIVE'::character varying::text,'CHARGE_OFF'::character varying::text ,'WRITE_OFF'::character varying::text]) THEN 'ACTIVE'::text
            ELSE 'CLOSED'::text
        END AS "Account_status_desc",
    	lp.name AS product_name,
    	to_char(l.createdon,'dd/mm/yyyy HH:MM:SS') AS createdon,
        CASE
            WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
            WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.principalchargedoffpending, 2)
            WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN 0::numeric
            ELSE round(l.principaloutstanding, 2)
        END AS "PrincipalOutstanding",
    	CASE
		   	WHEN l.loanstatus::text = 'CLOSED'::text THEN 0::numeric
		   	WHEN l.loanstatus::text = 'CHARGE_OFF'::text then round(lcd.interestchargedoffpending+lcd.chargeoffinterestpending, 2)
			WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN 0::numeric
			ELSE (select round(sum(l2.interestpending), 2) FROM platform_imp.loanschedule l2 WHERE l2.loanid::text = l.id::text and l2.installmentstatus not in ('FULLY_PAID','EXCESS_PAID'))
			END AS "Interestoutstanding", 
	  	round(l.calculatedcreditlimit, 2) AS "Creditlimit",   --add line
	    --round(l.creditlimit, 2) AS "Creditlimit",
		--l.riskassessment AS "RiskCategory",
	  	'' AS "RiskCategory",
		case
			WHEN l.loanstatus::text = 'CHARGE_OFF'::text THEN round(lcd.penaltychargedoffpending, 2)
			WHEN l.loanstatus::text = 'WRITE_OFF'::text THEN 0::numeric
        	else (SELECT 
				sum(round(l2.penaltypending, 2)) AS sum
				FROM platform_imp.loanschedule l2
				WHERE l2.loanid::text = l.id::text)
			end AS "Penaltyfeeoutstanding",
		round(l.chargescharged, 2) AS "RolloverFees"
	FROM platform_imp.basicuser usr
 	JOIN platform_imp.loan l ON usr.id::text = l.userid::text and l.loanstatus::text in ('ACTIVE','WRITE_OFF','CHARGE_OFF') and l.loanproductid='011d3bc1-4b5e-49b7-a103-bf1cecfac5c9'
-- 	LEFT JOIN platform_imp.userkycdetails ukyc ON usr.id::text = ukyc.userid::text
	LEFT JOIN platform_imp.loanbucket lb ON l.id::text = lb.loanid::text
 	JOIN platform_imp.customer usrc on usr.id = usrc.id 
	LEFT JOIN platform_imp.loanproduct lp ON l.loanproductid::text = lp.id::text
	LEFT JOIN platform_imp.loanchargeoffdata lcd ON l.id=lcd.loanid;
 End;
$procedure$
;

-- DROP PROCEDURE "dataReports".proc_rpt_u756loanreportclosed_bnpl(varchar, date);

CREATE OR REPLACE PROCEDURE "dataReports".proc_rpt_u756loanreportclosed_bnpl(IN requestid character varying, IN run_date date DEFAULT (concat(((now())::date - 1), ' ', '23:59:59'))::timestamp without time zone)
 LANGUAGE plpgsql
AS $procedure$
begin
 	truncate "dataReports".rpt_u756loanreportclosed_bnpl;
	insert into "dataReports".rpt_u756loanreportclosed_bnpl
select 
		requestid,
		usr.lastname AS "Surname",
	    usr.firstname AS "Forename1",
	    usr.middlename AS "Forename2",
        /*CASE
            WHEN ukyc.title IS NULL THEN ''::character varying
            ELSE ukyc.title
        END AS "Salutation",*/
	    '' AS "Salutation",
    	to_char(run_date,'dd/mm/yyyy') AS "BusinessDate",
		to_char(dob::DATE,'dd/mm/yyyy') AS "Date_of_Birth",
	    usr.id AS "Client_Number",
	    l.loanapplicationnumber AS "Mobile_Loan_Account_Number",
	    usrc.gender,
    	'KE'::text AS "Nationality",
	    usrc.identitytype AS "PrimaryID_type",
	    usrc.identitynumber AS "PrimaryID_Num",
	    concat('254', usr.username) AS "Mobile_Number",
	    'KE'::text AS "Postal_Country",
	    0 AS salary_band,
	    'Virtual Banking'::text AS "Lender_Branch_Name",
	    160 AS "Lender_Branch_Code",
	    'IN001'::text AS "Account_prod_type",
	    to_char(l.expecteddisbursementdate::DATE,'dd/mm/yyyy') AS "Date_Acct_Opened",
	    to_char(l.expectedfirstrepaymentdate::DATE,'dd/mm/yyyy') AS "Instalment_due_date",
	    round(l.principaldisbursed, 2) AS "Original_Amount",
	    round(l.principaldisbursed, 2) AS local_orig_amount,
		round(l.totalamountoutstanding, 2) AS "Current_balance",
		round(l.totalamountoutstanding, 2) AS "Overdue_balance",
        ' '::text AS "Overdue_date",
        0::double precision AS "Days_in_arrears",
       'Bucket 0'::text AS "Bucket",
		0::numeric AS "Instalment_arrears",
    	l.loanstatus AS "Account_Status",
        to_char(l.actualcloseddate::DATE,'dd/mm/yyyy') AS "Account_status_Date",
		' '::text AS "Reason_For_Closure",
    	l.loanperiod AS "Repayment_period",
    	''::text AS "Deferred_pymt_Date",
    	''::text AS "Deferred_pymt_amt",
		l.replayfrequency AS "Payment_freq",
		to_char(l.actualdisbursementdate::DATE,'dd/mm/yyyy') AS "Disbursement_Date",
	    round(l.totalexpectedcostofloan, 2) AS "Instalment_amount",
        CASE
            WHEN l.lastpaidon IS NULL THEN ' '::text
            ELSE to_char(l.lastpaidon::DATE,'dd/mm/yyyy')::text
        END AS "Latest_pymt_date",
        COALESCE(round(l.lastpaidamount, 2), 0::numeric) AS "Latest_pymt_Amt",
    	--COALESCE(round(l.lastinstallmentamount, 2), 0::numeric) AS "Latest_pymt_Amt",
        'CLOSED'::text AS "Account_status_desc",
    	lp.name AS product_name,
		to_char(l.createdon,'dd/mm/yyyy HH24:MI:SS') AS createdon,
        0::numeric AS "PrincipalOutstanding",
    	0::numeric as "Interestoutstanding", 
		round(l.calculatedcreditlimit, 2) AS "Creditlimit",   --add line
  		--round(l.creditlimit, 2) AS "Creditlimit",
		--l.riskassessment AS "RiskCategory",
		'' AS "RiskCategory",
        (SELECT 
				sum(round(l2.penaltypending, 2)) AS sum
				FROM platform_imp.loanschedule l2
				WHERE l2.loanid::text = l.id::text) AS "Penaltyfeeoutstanding",
		(SELECT 
		 	sum(round(l2.penaltycomponent, 2)) AS sum
           	FROM platform_imp.loanschedule l2
          	WHERE l2.loanid::text = l.id::text) AS "RolloverFees"
	FROM platform_imp.basicuser usr
 	JOIN platform_imp.loan l ON usr.id::text = l.userid::text and l.loanstatus::text in ('CLOSED','MATURED')
 --	LEFT JOIN userkycdetails ukyc ON usr.id::text = ukyc.userid::text
 	JOIN platform_imp.customer usrc on usr.id = usrc.id 
	LEFT JOIN platform_imp.loanbucket lb ON l.id::text = lb.loanid::text
	LEFT JOIN platform_imp.loanproduct lp ON l.loanproductid::text = lp.id::text;
  End;
$procedure$
;

