CREATE TABLE platform_imp.account (
	id varchar NOT NULL,
	createdby varchar NULL,
	createdon timestamp NULL,
	modifiedby varchar NULL,
	modifiedon timestamp NULL,
	transactiontime timestamp NULL,
	walletno varchar NULL,
	wallettypeid varchar NULL,
	wallettypename varchar NULL,
	productusermappingid varchar NULL,
	producttype varchar NULL,
	instancetype varchar NULL,
	walletstatus varchar NULL,
	currencyid varchar NULL,
	ownerid varchar NULL,
	minimumbalance numeric(32, 8) NULL,
	uppertotalbalancelimit numeric(32, 8) NULL,
	lowertotalbalancelimit numeric(32, 8) NULL,
	dailymaxdebitamount numeric(32, 8) NULL,
	dailymaxcreditamount numeric(32, 8) NULL,
	dailymaxtotalamount numeric(32, 8) NULL,
	dailymaxcreditcount int4 NULL,
	dailymaxdebitcount int4 NULL,
	dailymaxtotalcount int4 NULL,
	weeklymaxdebitamount numeric(32, 8) NULL,
	weeklymaxcreditamount numeric(32, 8) NULL,
	weeklymaxtotalamount numeric(32, 8) NULL,
	weeklymaxcreditcount int4 NULL,
	weeklymaxdebitcount int4 NULL,
	weeklymaxtotalcount int4 NULL,
	monthlymaxdebitamount numeric(32, 8) NULL,
	monthlymaxcreditamount numeric(32, 8) NULL,
	monthlymaxtotalamount numeric(32, 8) NULL,
	monthlymaxcreditcount int4 NULL,
	monthlymaxdebitcount int4 NULL,
	monthlymaxtotalcount int4 NULL,
	active bool NULL,
	needssettlement bool NULL,
	settlementinterval int4 NULL,
	threshholdsettlementamount numeric(32, 8) NULL,
	settlementaccountid varchar NULL,
	hotaccount bool NULL,
	consolidatetransactions bool NULL,
	defaultaccount bool NULL,
	checksum varchar NULL,
	creditlimitstatus varchar(50) NULL,
	remarks varchar(60) NULL,
	creditlimittype varchar(60) NULL,
	externalwalletcode varchar NULL,
	needssettlementforfees bool NULL,
	settlementintervalforfees numeric NULL,
	settlementaccountidforfees varchar(100) NULL,
	applicationmappingid varchar(50) NULL,
	isshareable bool NULL,
	minimumamount numeric NULL,
	shareableusersjson varchar NULL,
	targetamount numeric NULL,
	"type" varchar NULL,
	parentid varchar NULL,
	thresholdlimitid varchar NULL,
	status varchar NULL
);


-- platform_imp.accountbalance definition

-- Drop table

-- DROP TABLE platform_imp.accountbalance;

CREATE TABLE platform_imp.accountbalance (
	id varchar NOT NULL,
	createdby varchar NULL,
	createdon timestamp NULL,
	modifiedby varchar NULL,
	modifiedon timestamp NULL,
	creditamount numeric(32, 8) NULL,
	debitamount numeric(32, 8) NULL,
	totalbalance numeric(32, 8) NULL,
	reservebalance numeric(32, 8) NULL,
	unsettledamount numeric(32, 8) NULL,
	settleafter timestamp NULL,
	settlementrequired bool NULL,
