---Views---
-- platform_imp.glsummaryreportbnpl source

CREATE OR REPLACE VIEW platform_imp.glsummaryreportbnpl
AS SELECT date(g.summarydate) AS "Date",
    w3.externalwalletcode AS "AccountID",
    w3.name AS "Description",
    'KES'::text AS "Currency ID",
    round(g.totalbalance - g.creditamounttoday + g.debitamounttoday, 2) AS "Opening Balance",
    round(g.debitamounttoday, 2) AS "Debit Amount",
    round(g.creditamounttoday, 2) AS "Credit Amount",
    round(g.totalbalance, 2) AS "Closing Balance"
   FROM platform_imp.glsummary g
     JOIN platform_imp.wallettype w3 ON g.wallettypeid::text = w3.id::text
  WHERE w3.internalwallet = false;


-- platform_imp.glsummaryreportbnpl_1 source

CREATE OR REPLACE VIEW platform_imp.glsummaryreportbnpl_1
AS SELECT date(g.summarydate) AS "Date",
    w3.externalwalletcode AS "AccountID",
    w3.name AS "Description",
    'KES'::text AS "Currency ID",
    round(g.totalbalance - g.creditamounttoday + g.debitamounttoday, 2) AS "Opening Balance",
    round(g.debitamounttoday, 2) AS "Debit Amount",
    round(g.creditamounttoday, 2) AS "Credit Amount",
    round(g.totalbalance, 2) AS "Closing Balance"
   FROM platform_imp.glsummary g
     JOIN platform_imp.wallettype w3 ON g.wallettypeid::text = w3.id::text
  WHERE w3.internalwallet = false;
  
