-- DROP PROCEDURE platform_imp.basicuserdata(inout json);

CREATE OR REPLACE PROCEDURE platform_imp.basicuserdata(INOUT request json)
 LANGUAGE plpgsql
AS $procedure$
DECLARE
	JsonObject ALIAS FOR $1;
  filter_String VARCHAR;
    _keyValue text;
   _value text;
  column_string varchar;
 i json;
 
  sql VARCHAR;
   BEGIN
	
FOR _keyValue,_value IN
       SELECT * FROM json_each_text(request::json->'filters')
    LOOP
       -- do some math operation on its corresponding value
  filter_String= concat(filter_String,' and ',_keyValue,'=','''',_value,'''');
    RAISE NOTICE '%:',filter_String;
    END LOOP;
  

  FOR i IN SELECT * FROM json_array_elements(request::json->'columnData')
  loop
   column_string=concat(i->>'tableColumn',' as ',i->>'columnDisplayName',',',column_string);
   
  END LOOP;
  column_string= substr(column_string, 1, length(column_string) - 1);
  RAISE NOTICE '%',column_string;
  sql:='select ';
  
 IF column_string IS NOT NULL then
      sql:=concat(sql,column_string);
   END IF;
   sql:=concat(sql,' FROM basicuser where 1=1');
	
 --  sql := 'SELECT username, roletype, userdisplayname FROM basicuser where 1=1';
    --sq := 'select to_json(tt) from (SELECT * FROM json_test3) tt where 1=1 and  ';
	
  IF filter_String IS NOT NULL then
      sql:=concat(sql,filter_String);
   END IF;
  
  RAISE NOTICE 'Sql %',sql;
--open result for  execute  sql; 
sql:=concat(' select json_agg(t) from ','(',sql,')',' t ');
 RAISE NOTICE 'Sql %',sql;
execute  sql into request ;
--RAISE NOTICE 'response %',request;

END;
$procedure$
;

-- DROP PROCEDURE platform_imp.block_unblock_based_on_dpd_sp(varchar);

CREATE OR REPLACE PROCEDURE platform_imp.block_unblock_based_on_dpd_sp(IN processname character varying)
 LANGUAGE plpgsql
AS $procedure$
declare
	DPD_BLOCK_STR VARCHAR :='';
	DPD_BLOCK INTEGER;
	INSERT_HOLD REFCURSOR;
	BORROWER_ID platform_imp.CUSTOMER.ID%TYPE; 
	AUTID_ID VARCHAR;
	REMARKS_VAL VARCHAR ;
	JSON_STR VARCHAR;
	BEGIN
		 --SAVEPOINT DPD_SP;  
	SELECT g2.VALUE into DPD_BLOCK_STR FROM platform_imp.GLOBALCONFIGURATION g2 WHERE LOWER(PARAMETERNAME) ='dpd' AND PROCESS ='DPD_BLOCK';
IF DPD_BLOCK_STR IS NOT NULL THEN
		DPD_BLOCK := TO_NUMBER(DPD_BLOCK_STR, '9G999g999');
	ELSE
		DPD_BLOCK :=0;
	END IF;
 IF DPD_BLOCK > 0 THEN
		IF processName ='BLOCK' THEN
			REMARKS_VAL := 'Blocked by System Due to Late Repayment';
			OPEN INSERT_HOLD FOR SELECT B.ID FROM platform_imp.CUSTOMER B INNER JOIN platform_imp.CREDITLIMIT C2  ON B.ID = C2.USERID
									inner join platform_imp.customercomplianceinfo ci on ci.userid = b.id WHERE C2.CREDITLIMITSTATUS = 'ACTIVE' AND ci.WORSTDPD >= DPD_BLOCK;
			
			LOOP
				    FETCH INSERT_HOLD INTO BORROWER_ID;
				    EXIT WHEN  not found  ;
					UPDATE platform_imp.creditlimit   SET CREDITLIMITSTATUS  = 'BLOCKED' , CODE = 'BC03',REMARKS  = REMARKS_VAL, limitlastupdatedon = current_date WHERE USERID = BORROWER_ID;
					JSON_STR := '{"creditLimitStatus":"BLOCKED","remarks":"'||REMARKS_VAL||'"}';	
					--SELECT REGEXP_REPLACE(ENCODE('uuid_generate_v4()','HEX'), '([A-F0-9]{8})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{12})', '\1-\2-\3-\4-\5') into AUTID_ID FROM dual;
				    SELECT uuid_in(md5(random()::text || random()::text)::cstring)  into AUTID_ID;	
			        INSERT INTO MAKERCHECKERAUDIT
						(AUDITID, ID, CREATEDBY, CREATEDON, MODIFIEDBY, MODIFIEDON, APPROVALSTATUS, MANAGEDOBJECTJSON, REMARKS, MODULENAME)
						VALUES(AUTID_ID, BORROWER_ID,
							'SYSTEM', current_timestamp,
							'SYSTEM', current_timestamp,
							'AUTOAPPROVED', to_jsonb(JSON_STR),
							REMARKS_VAL, 'CreditLimit');
			   	END LOOP;
		ELSIF processName ='UNBLOCK' THEN
		   REMARKS_VAL := '';
			OPEN INSERT_HOLD FOR SELECT B.ID FROM platform_imp.CUSTOMER B INNER JOIN platform_imp.CREDITLIMIT C2  ON B.ID = C2.USERID 
				inner join platform_imp.customercomplianceinfo ci on ci.userid = b.id WHERE C2.CREDITLIMITSTATUS = 'BLOCKED' AND ci.worstdpd < DPD_BLOCK AND C2.CODE = 'BC03' AND C2.REMARKS='Blocked by System Due to Late Repayment';
			
		LOOP
			    FETCH INSERT_HOLD INTO BORROWER_ID;
			    EXIT WHEN  not found;
				UPDATE platform_imp.CREDITLIMIT   SET CREDITLIMITSTATUS  = 'ACTIVE' , CODE = '',REMARKS  = '', limitlastupdatedon = current_date WHERE USERID = BORROWER_ID;
				JSON_STR := '{"creditLimitStatus":"ACTIVE","remarks":"'||REMARKS_VAL||'"}';
				--SELECT regexp_replace(rawtohex(sys_guid()), '([A-F0-9]{8})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{12})', '\1-\2-\3-\4-\5') into AUTID_ID FROM dual;
			    SELECT uuid_in(md5(random()::text || random()::text)::cstring)  into AUTID_ID;	
				INSERT INTO platform_imp.MAKERCHECKERAUDIT
					(AUDITID, ID, CREATEDBY, CREATEDON, MODIFIEDBY, MODIFIEDON, APPROVALSTATUS, MANAGEDOBJECTJSON, REMARKS, MODULENAME)
					VALUES(AUTID_ID, BORROWER_ID,
						'SYSTEM', current_timestamp,
						'SYSTEM', current_timestamp,
						'AUTOAPPROVED', to_jsonb(JSON_STR),
						REMARKS_VAL, 'CreditLimit');
		END LOOP;
	        
	        close INSERT_HOLD;
			OPEN INSERT_HOLD FOR SELECT B.ID FROM platform_imp.CUSTOMER B INNER JOIN CREDITLIMIT C2  ON B.ID = C2.USERID inner join platform_imp.customercomplianceinfo cinf on cinf.userid=B.id WHERE C2.CREDITLIMITSTATUS = 'BLOCKED' AND cinf.BICOLLECTABILITY = 1 AND C2.CODE = 'BC07' AND C2.REMARKS='Due to Worst Collectability';
			
		LOOP
			    FETCH INSERT_HOLD INTO BORROWER_ID;
			    EXIT when not found;
				UPDATE CREDITLIMIT   SET CREDITLIMITSTATUS  = 'ACTIVE' , CODE = '',REMARKS  = '' WHERE USERID = BORROWER_ID;
				JSON_STR := '{"creditLimitStatus":"ACTIVE","remarks":"'||REMARKS_VAL||'"}';
				--SELECT regexp_replace(rawtohex(sys_guid()), '([A-F0-9]{8})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{12})', '\1-\2-\3-\4-\5') into AUTID_ID FROM dual;
				SELECT uuid_in(md5(random()::text || random()::text)::cstring)  into AUTID_ID;	
			    INSERT INTO MAKERCHECKERAUDIT
					(AUDITID, ID, CREATEDBY, CREATEDON, MODIFIEDBY, MODIFIEDON, APPROVALSTATUS, MANAGEDOBJECTJSON, REMARKS, MODULENAME)
					VALUES(AUTID_ID, BORROWER_ID,
						'SYSTEM', current_timestamp,
						'SYSTEM', current_timestamp,
						'AUTOAPPROVED', to_jsonb(JSON_STR),
						REMARKS_VAL, 'CreditLimit');
		END LOOP;
		   
		END IF;
	END IF;
		    -- If any exception occurs
		EXCEPTION
		WHEN OTHERS THEN
		      -- We roll back to the savepoint.
		  -- ROLLBACK TO DPD_SP;
		   -- We can raise again,
		   -- If we want to handle it on java scheduler
		   RAISE;
END ;
$procedure$
;

