-- DROP FUNCTION platform_imp.fnpocfinal(json);

CREATE OR REPLACE FUNCTION platform_imp.fnpocfinal(jsonv json)
 RETURNS TABLE(txt json)
 LANGUAGE plpgsql
AS $function$
DECLARE
	TABLECOLUMN VARCHAR;
    FILTERSTRING VARCHAR;
    RECORDSET RECORD;
    SQLSTRING VARCHAR;
   	LOOPCOUNTER integer;
    FOOTERKEYVALUENAME VARCHAR;
    FOOTERKEYVALUEDATA VARCHAR;
	FOOTERVALUE VARCHAR;
   
begin
		--FETCHING PAGINATION
	FOR FOOTERKEYVALUENAME,FOOTERKEYVALUEDATA IN
     SELECT * FROM json_each_text(JsonV::json->'pagination') 
    loop
	  	    FOOTERVALUE= concat(FOOTERVALUE, FOOTERKEYVALUENAME,' ', FOOTERKEYVALUEDATA);
    	--RAISE NOTICE '%:',FOOTERVALUE;
    END LOOP; 
	
	TABLECOLUMN:='';
    FILTERSTRING:='';
    	for LOOPCOUNTER in 1..(select json_array_length((jsonV->>'columnData')::json)) loop
		IF LOOPCOUNTER=1 then
        --TABLECOLUMN:=TABLECOLUMN||LOOPCOUNTER;
        TABLECOLUMN:=TABLECOLUMN||''''||((((jsonV::json->>'columnData')::json->LOOPCOUNTER-1))::json->>'columnDisplayName')||''','||((((jsonV::json->>'columnData')::json->LOOPCOUNTER-1))::json->>'tableColumn');
        else
        --TABLECOLUMN:=TABLECOLUMN||','||LOOPCOUNTER;
        TABLECOLUMN:=TABLECOLUMN||','||''''||(((jsonV::json->>'columnData')::json->LOOPCOUNTER-1)::json->>'columnDisplayName')||''','||(((jsonV::json->>'columnData')::json->LOOPCOUNTER-1)::json->>'tableColumn');
        END IF;
	END LOOP;  
 RAISE NOTICE 'TABLECOLUMN %',TABLECOLUMN;


    
	LOOPCOUNTER:=1;
    for RECORDSET in select row_number() over() as id,(json_each_text((jsonV::json->>'filters')::json)).key as key,(json_each_text((jsonV::json->>'filters')::json)).value as value loop
	    IF LOOPCOUNTER=1 THEN
	      FILTERSTRING:=FILTERSTRING||RECORDSET."key"||''||RECORDSET."value"||'';
	     --RAISE NOTICE 'FILTERSTRING %',FILTERSTRING;
	    END IF;
	    LOOPCOUNTER:=LOOPCOUNTER+1;
    END LOOP;
   
     SQLSTRING := 'select json_build_object('||TABLECOLUMN ||') RECORDSET from basicuser  '|| FILTERSTRING || FOOTERVALUE ||';';
    --RETURN QUERY EXECUTE SQLSTRING;
   --RAISE NOTICE 'SQLSTRING %',SQLSTRING;
END;
$function$
;

-- DROP FUNCTION platform_imp.fnpocwithsqlquery(json);

CREATE OR REPLACE FUNCTION platform_imp.fnpocwithsqlquery(jsonv json)
 RETURNS TABLE(txt json)
 LANGUAGE plpgsql
AS $function$
DECLARE
	ReportIDS VARCHAR;
	ReportKey VARCHAR;
    ReportKeyData VARCHAR;
    FILTERSTRING VARCHAR;
    RECORDSET RECORD;
   	ReportQueryString character varying(10000);
    SQLSTRING VARCHAR;
   	LOOPCOUNTER integer;
    FOOTERKEYVALUENAME VARCHAR;
    FOOTERKEYVALUEDATA int;
	FOOTERVALUE VARCHAR;
   
begin
	--FETCHING PAGINATION
	  FOR FOOTERKEYVALUENAME,FOOTERKEYVALUEDATA IN
	     SELECT * FROM json_each_text(JsonV::json->'pagination') 
	    loop
		  	    FOOTERVALUE= concat(FOOTERVALUE, ' ', FOOTERKEYVALUENAME,' ', FOOTERKEYVALUEDATA);
	    END LOOP;
	  
   	--FETCHING ReportID
	FOR ReportKey,ReportKeyData IN
    SELECT * FROM json_each_text(JsonV::json->'reportquery') 
    loop
	  	ReportIDS = concat(ReportIDS, ReportKey,' ', ReportKeyData);
	END LOOP; 
		
   --Fecthing SQL QUERY basis of reportID
	select reportsql into ReportQueryString from platform_imp.querytable where reportid = '1';
	RAISE NOTICE 'ReportQueryString %',ReportQueryString;
	

   --Fecthing Filters
	FILTERSTRING:='';
	LOOPCOUNTER:=1;
    for RECORDSET in select row_number() over() as id,(json_each_text((jsonV::json->>'filters')::json)).key as key,(json_each_text((jsonV::json->>'filters')::json)).value as value loop
	    IF LOOPCOUNTER=1 THEN
	      FILTERSTRING:=FILTERSTRING||RECORDSET."key"||''||RECORDSET."value"||'';
	    END IF;
	    LOOPCOUNTER:=LOOPCOUNTER+1;
    END LOOP;
     
     SQLSTRING := ReportQueryString || '  ' || FILTERSTRING || FOOTERVALUE ||';';
     RETURN QUERY EXECUTE SQLSTRING;
	 RAISE NOTICE 'SQLSTRING %',SQLSTRING;
END;
$function$
;

-- DROP FUNCTION platform_imp.fnpocwithsqlquery_1(json);

CREATE OR REPLACE FUNCTION platform_imp.fnpocwithsqlquery_1(jsonv json)
 RETURNS TABLE(txt json)
 LANGUAGE plpgsql
AS $function$
DECLARE
	FILTERSTRING VARCHAR;
    RECORDSET RECORD;
   	ReportQuery character varying(10000);
    ReportQueryString character varying(10000);
    SQLSTRING VARCHAR;
   	LOOPCOUNTER numeric;
    FOOTERKEYVALUENAME VARCHAR;
    FOOTERKEYVALUEDATA int;
	FOOTERVALUE VARCHAR;
	TABLECOLUMN VARCHAr;
	column_string varchar;
    tempvar varchar;
	request json;
	i json;
  begin
	--FETCHING PAGINATION
	  FOR FOOTERKEYVALUENAME,FOOTERKEYVALUEDATA IN
	  SELECT * FROM json_each_text(JsonV::json->'pagination') 
	  loop
		   FOOTERVALUE= concat(FOOTERVALUE, ' ', FOOTERKEYVALUENAME,' ', FOOTERKEYVALUEDATA);
	  END LOOP;
 
	 --Fecthing SQL QUERY basis of reportID
	 
	select reportsql  into ReportQuery from platform_imp.querytable where reportid = '2';
	RAISE NOTICE 'ReportQuery %',ReportQuery;
	 
		select reportfilter  into ReportQueryString from platform_imp.querytable where reportid = '2';
		--RAISE NOTICE 'ReportQueryString %',ReportQueryString;
		
		LOOPCOUNTER:=1;
		TABLECOLUMN:='';
	    ReportQueryString=ReportQueryString::json;
	  	request  := ReportQueryString;
	  	FOR i IN SELECT * FROM json_array_elements(request::json->'menu_options')
	  	loop
			TABLECOLUMN:=i::json->>'Conditiontrue';   
			tempvar:=i::json->>'id';   
			FILTERSTRING=concat(tempvar,'-',TABLECOLUMN);
			RAISE NOTICE '%',FILTERSTRING;
	  	END LOOP;
  

    
  SQLSTRING := ReportQueryString || '  ' || FOOTERVALUE ||';';
     --RETURN QUERY EXECUTE SQLSTRING;
	 --RAISE NOTICE 'SQLSTRING %',SQLSTRING;
END;
$function$
;

-- DROP FUNCTION platform_imp.getbasicuser(varchar);

CREATE OR REPLACE FUNCTION platform_imp.getbasicuser(filters character varying)
 RETURNS TABLE(email character varying, id character varying)
 LANGUAGE plpgsql
AS $function$
DECLARE
	JsonObject ALIAS FOR $1;
  filter_String VARCHAR;
 
  sql VARCHAR;
  --sq json; 
BEGIN
	

Select string_agg(replace(replace(replace(tt,',', '='''),')',''''),'(',''),' and ') into filter_String from (
Select 
concat(json_each_text(json_array_elements(json_extract_path('{"roletype" : "MERCHANT","IsActive" : true,"filters": [
  {
    "roletype":"OPERATION"
  }]}','filters')))) as tt
	
	) as base;
	
    sql := 'SELECT email,id FROM basicuser where 1=1 and ';
    --sq := 'select to_json(tt) from (SELECT * FROM json_test3) tt where 1=1 and  ';
	
    IF filter_String IS NOT NULL then
    	   sql := sql ||  (filter_String) ;
   END IF;

    RETURN QUERY EXECUTE sql;

END;
$function$
;

-- DROP PROCEDURE platform_imp.glsnapshot(timestamp);

CREATE OR REPLACE PROCEDURE platform_imp.glsnapshot(IN today timestamp without time zone)
 LANGUAGE sql
AS $procedure$
with temp_glsummary_today as
(select wt.id as wallettypeid, COALESCE(sum(wtx.debitamount),0) as debitamounttoday, COALESCE(sum(wtx.creditamount),0) as creditamounttoday
from platform_imp."wallettype" wt left join platform_imp."transaction" wtx on wt.id = wtx.wallettypeid and date(wtx.createdon) = (date(today) -1)
group by wt.id),
"temp_glsummary_total" as
(SELECT * FROM (
SELECT wallettypeid, currencyid, instancetype, creditamount,debitamount,totalbalance, creditamounttoday,debitamounttoday,summarydate, ROW_NUMBER() OVER (PARTITION BY wallettypeid order by summarydate DESC) AS rn from platform_imp."glsummary" where date(summarydate) < (date(today) -1)) sq WHERE sq.rn=1)
insert into platform_imp."glsummary"
select wt.id, wt.currencyid, wt.wallettype, COALESCE(gtd.creditamounttoday,0)+ COALESCE(gtl.creditamount,0) as creditamount, COALESCE(gtd.debitamounttoday,0)+ COALESCE(gtl.debitamount,0) as debitamount, COALESCE(gtd.creditamounttoday,0) + COALESCE(gtl.creditamount,0) - COALESCE(gtd.debitamounttoday,0) - COALESCE(gtl.debitamount,0) as totalbalance, COALESCE(gtd.creditamounttoday,0) as creditamounttoday, COALESCE(gtd.debitamounttoday,0) as debitamounttoday,
(date(today) -1) as summarydate
from platform_imp."wallettype" wt left join "temp_glsummary_total" as gtl on wt.id=gtl.wallettypeid
left join "temp_glsummary_today" gtd on gtd.wallettypeid = gtl.wallettypeid;
$procedure$
;

