-- DROP PROCEDURE platform_imp.proc_loanscore();

CREATE OR REPLACE PROCEDURE platform_imp.proc_loanscore()
 LANGUAGE sql
AS $procedure$
TRUNCATE table platform_imp. loansummary;

INSERT INTO platform_imp.loansummary(userid,
NMobileOpenLoan,
NMobileLoanEver,
NMobileLoanClosedL12M,
MSinceMobileLoanClosed,
NMaxDPDMobileLoanL12M,
NMaxDPDMobileLoanL6M,
NmobileLoansPast1M,
days_betn_loans,
createdOn,
modifiedOn,
nmobileloanspast3m,
nmobileloanspast12m,
nmobileloanspenalty12m,
nmobileloanclosed,
nmobileloansoverdue12m,
nmobileloanspast6m,
amobileloanspenalty3m,
amobileloanspenalty12m,
nmobileloansoverdue24m,
nmobileloanspast36m,
nriskcategorymedium24m
)
(WITH ln as (select distinct userid from platform_imp.loan)

SELECT distinct ln.userid, coalesce(q1.nMobileOpenLoan,0) as nmobileopenloan,
coalesce(q2.nmobileloanever,0) as nmobileloanever, coalesce(q3.nmobileloanclosedl12m,0) as nmobileloanclosedl12m, coalesce(q5.msincemobileloanclosed,0) as msincemobileloanclosed, coalesce(q7.nmaxdpdmobileloanl12m, 0) as nmaxdpdmobileloanl12m,
coalesce(q8.nmaxdpdmobileloanl6m,0) as nmaxdpdmobileloanl6m, coalesce(q20.nmobileloanspast1m,0) as nmobileloanspast1m, coalesce(q22.days_betn_loans,0) as days_betn_loans,
now() as createdon, now() as modifiedOn,
coalesce(q23.nmobileloanspast3m,0) as nmobileloanspast3m,coalesce(q24.nmobileloanspast12m,0) as nmobileloanspast12m,coalesce(q25.nmobileloanspenalty12m,0) as nmobileloanspenalty12m,coalesce(q26.nmobileloanclosed,0) as nmobileloanclosed,coalesce(q27.nmobileloansoverdue12m,0) as nmobileloansoverdue12m,coalesce(q28.nmobileloanspast6m,0) as nmobileloanspast6m,coalesce(q29.amobileloanspenalty3m,0) as amobileloanspenalty3m,coalesce(q30.amobileloanspenalty12m,0) as amobileloanspenalty12m,coalesce(q31.nmobileloansoverdue24m,0) as nmobileloansoverdue24m,coalesce(q32.nmobileloanspast36m,0) as nmobileloanspast36m,coalesce(q33.nriskcategorymedium24m,0) as nriskcategorymedium24m
FROM ln
LEFT OUTER JOIN
(Select userid, count(*) as nMobileOpenLoan from platform_imp.loan
WHERE loanstatus = 'ACTIVE' or loanstatus = 'WRITTEN_OFF' or loanstatus = 'CHARGE_OFF' GROUP BY userid) q1 on q1.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanever from platform_imp.loan GROUP BY userid) q2 on q2.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanclosedl12m from platform_imp.loan where loanstatus in ( 'CLOSED','MATURED')
and date_part('day',now()-actualcloseddate) < 365 GROUP BY userid) q3 on q3.userid = ln.userid
LEFT OUTER JOIN
(select userid, case when loanstatus not in ( 'CLOSED','MATURED') then 0 else
ROUND(date_part('day', now()-modifiedon)/30) END as msincemobileloanclosed from platform_imp.loan order by createdon desc limit 1) q5 on q5.userid = ln.userid
LEFT OUTER JOIN
(select sq2.userid, max(sq2.days) as nmaxdpdmobileloanl12m from
(select userid, max(DATE_PART('day', actualcloseddate - expectedFirstRepaymentDate)) AS days from platform_imp.loan
where loanstatus in ( 'CLOSED','MATURED') and actualcloseddate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualcloseddate) <=365 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from platform_imp.loan
where loanstatus not in ( 'CLOSED','MATURED')
and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq2 GROUP BY sq2.userid) q7 on q7.userid = ln.userid
LEFT OUTER JOIN
(select userid, max(days) as nmaxdpdmobileloanl6m from
(select userid, max(DATE_PART('day', actualcloseddate - expectedFirstRepaymentDate)) AS days from platform_imp.loan
where loanstatus in ( 'CLOSED','MATURED') and actualcloseddate > expectedFirstRepaymentDate
and DATE_PART('day', NOW()- actualcloseddate) <=180 GROUP BY userid
UNION ALL
select userid, max(DATE_PART('day', NOW() - expectedFirstRepaymentDate)) AS days from platform_imp.loan
where loanstatus not in ( 'CLOSED','MATURED') and NOW() > expectedFirstRepaymentDate GROUP BY userid) AS sq3 GROUP BY sq3.userid) q8 on q8.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast1m from platform_imp.loan
where date_part('day', now()-createdon) < 30 GROUP BY userid) q20 on q20.userid = ln.userid
LEFT OUTER JOIN
(select sq5.userid, date_part('day', sq5.new_date- sq5.prev_date) as days_betn_loans from (
select sq4.userid, sq4.prev_date, sq4.new_date, ROW_NUMBER() OVER ( partition by sq4.userid order by sq4.createdon desc) as rowno from (
select lo.userid, lo.createdon, lag(lo.actualdisbursementdate) over (partition by lo.userid order by lo.createdon)
as prev_date, lo.actualdisbursementdate as new_date from platform_imp.loan lo order by createdon desc) as sq4) as sq5 where rowno=1) q22 on q22.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast3m from platform_imp.loan
where date_part('day', now()-createdon) < 90 GROUP BY userid) q23 on q23.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast12m from platform_imp.loan
where date_part('day', now()-createdon) < 365 GROUP BY userid) q24 on q24.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(l.*) as nmobileloanspenalty12m 
from platform_imp.loan l inner join platform_imp.loanschedule ls on l.id=ls.loanid
where date_part('day', now()-l.createdon) < 365 and (ls.penaltycomponent is not null and ls.penaltycomponent > 0) GROUP BY l.userid) q25 on q25.userid = ln.userid
LEFT OUTER JOIN
(SELECT userid, count(*) as nmobileloanclosed from platform_imp.loan where loanstatus in ('CLOSED','MATURED') GROUP BY userid) q26 on q26.userid = ln.userid
LEFT OUTER JOIN
(select userid,count(*) as nmobileloansoverdue12m 
from platform_imp.loan l inner join platform_imp.loanschedule ls on l.id=ls.loanid
where date_part('day', now()-l.createdon) < 365 and (ls.penaltycomponent is not null and ls.penaltycomponent > 0) GROUP BY l.userid) q27 on q27.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast6m from platform_imp.loan
where date_part('day', now()-createdon) < 180 GROUP BY userid) q28 on q28.userid = ln.userid
LEFT OUTER JOIN
(select l.userid, sum(ls.penaltycomponent) as amobileloanspenalty3m 
from platform_imp.loan l
join platform_imp.loanschedule ls on l.id=ls.loanid
where date_part('day', now()-l.createdon) < 90 GROUP BY userid) q29 on q29.userid = ln.userid
LEFT OUTER JOIN
(select l.userid, sum(ls.penaltycomponent) as amobileloanspenalty12m 
from platform_imp.loan l
join platform_imp.loanschedule ls on l.id=ls.loanid
where date_part('day', now()-l.createdon) < 365 GROUP BY userid) q30 on q30.userid = ln.userid
LEFT OUTER JOIN
(select l.userid,count(l.*) as nmobileloansoverdue24m 
from platform_imp.loan l inner join platform_imp.loanschedule ls on l.id=ls.loanid
where date_part('day', now()-l.createdon) < 730 and (ls.penaltycomponent is not null and ls.penaltycomponent > 0) GROUP BY userid) q31 on q31.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nmobileloanspast36m from platform_imp.loan
where date_part('day', now()-createdon) < 1095 GROUP BY userid) q32 on q32.userid = ln.userid
LEFT OUTER JOIN
(select userid, count(*) as nriskcategorymedium24m from platform_imp.loan
where date_part('day', now()-createdon) < 730 and riskassessment in ('MEDIUM RISK','REPEAT MEDIUM RISK') GROUP BY userid) q33 on q33.userid = ln.userid);
$procedure$
;

-- DROP PROCEDURE platform_imp.procedure_name(in varchar, inout refcursor);

CREATE OR REPLACE PROCEDURE platform_imp.procedure_name(IN _parameter character varying, INOUT result refcursor)
 LANGUAGE plpgsql
AS $procedure$         
BEGIN
open result for SELECT   * from platform_imp.basicuser where id=_parameter; 
END;
$procedure$
;

