-- scheduler.arttha_job_execution definition

-- Drop table

-- DROP TABLE scheduler.arttha_job_execution;

CREATE TABLE scheduler.arttha_job_execution (
	job_id int8 NULL,
	job_executed_by varchar NULL,
	start_dt_time timestamp NULL,
	end_dt_time timestamp NULL,
	status varchar NULL,
	message varchar NULL,
	job_exec_id varchar NOT NULL,
	CONSTRAINT arttha_job_execution_pkey PRIMARY KEY (job_exec_id)
);


-- scheduler.arttha_jobs definition

-- Drop table

-- DROP TABLE scheduler.arttha_jobs;

CREATE TABLE scheduler.arttha_jobs (
	job_id int8 NOT NULL,
	job_desc varchar NULL,
	job_name varchar NULL,
	job_type varchar NULL,
	job_url varchar NULL,
	notification_recepients varchar NULL,
	notification bit(1) NULL,
	process_type varchar NULL,
	payload varchar NULL,
	schedule_time varchar NULL,
	status bit(1) NULL,
	creation_time timestamp NULL,
	last_updation_time timestamp NULL,
	tenant varchar NULL,
	locale varchar NULL,
	CONSTRAINT artta_jobs_pkey PRIMARY KEY (job_id)
);


-- scheduler.batch_job_execution definition

-- Drop table

-- DROP TABLE scheduler.batch_job_execution;

CREATE TABLE scheduler.batch_job_execution (
	job_execution_id int8 NOT NULL,
	"version" int8 NULL,
	job_instance_id int8 NOT NULL,
	create_time timestamp NOT NULL,
	start_time timestamp NULL,
	end_time timestamp NULL,
	status varchar(10) NULL,
	exit_code varchar(2500) NULL,
	exit_message varchar(2500) NULL,
	last_updated timestamp NULL,
	job_configuration_location varchar(2500) NULL
);


