-- scheduler.process_master definition

-- Drop table

-- DROP TABLE scheduler.process_master;

CREATE TABLE scheduler.process_master (
	id varchar(50) NOT NULL,
	createdby varchar(50) NULL,
	modifiedby varchar(50) NULL,
	createdon timestamp NULL,
	modifiedon timestamp NULL,
	processname varchar(200) NULL,
	description varchar(1000) NULL,
	jobcode varchar(1000) NULL,
	schedule varchar(50) NULL,
	"type" varchar(50) NULL,
	"sequence" varchar(50) NULL,
	dependency varchar(50) NULL,
	resturl varchar(2000) NULL,
	cantriggeredmanually numeric(1) NULL,
	tenant varchar(200) NULL,
	locale varchar(100) NULL,
	jobmode varchar(100) NULL,
	CONSTRAINT sys_c0024594 PRIMARY KEY (id)
);
CREATE INDEX process_master_jobcode_idx ON scheduler.process_master USING btree (jobcode);
CREATE INDEX process_master_processname_idx ON scheduler.process_master USING btree (processname);
CREATE UNIQUE INDEX sys_c0026594 ON scheduler.process_master USING btree (id);


